INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(5763020, 'Weeping Idol', '泣神的石像', '泣き神の石像', 'Effect Monster', 'Rock', 'DARK', 2, NULL, 500, '把自己墓地存在的1只调整从游戏中除外发动。这张卡从手卡特殊召唤。'),
(39103226, 'Weighbridge', '地磅计量', '台貫計量', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上的怪兽数量比自己场上的怪兽多2只以上的场合才能发动。对方直到自身场上的怪兽变成1只为止必须送去墓地。'),
(42548470, 'Weights & Zenmaisures', '摇晃的发条秤', '揺れる発条秤', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的2只等级不同的名字带有「发条」的怪兽发动。对方选那之内1只，另1只怪兽的等级直到结束阶段时变成和对方选的怪兽相同。对方选等级低的怪兽的场合，那之后自己可以从卡组抽1张卡。'),
(96576187, 'Weiss, Lightsworn Archfiend', '光道恶魔 拜斯', 'ライトロード・デーモン ヴァイス', 'Tuner Monster', 'Fiend', 'LIGHT', 4, NULL, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡让1张其他的「光道」卡回到卡组最上面才能发动。这张卡从手卡特殊召唤。那之后，从自己卡组上面把2张卡送去墓地。 ②：这张卡从卡组送去墓地的场合，以「光道恶魔 魏丝」以外的自己墓地1只「光道」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(5380979, 'Welcome Labrynth', '欢迎光临拉比丽斯', 'ウェルカム・ラビュリンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「拉比林斯迷宫」怪兽特殊召唤。这张卡的发动后，直到下个回合的结束时自己不是恶魔族怪兽不能从卡组·额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。这张卡在自己场上盖放。这个效果在这张卡送去墓地的回合不能发动。'),
(300302076, 'Welcome to the Jungle', NULL, NULL, 'Skill Card', 'Tania', NULL, NULL, NULL, NULL, NULL),
(96643568, 'Wetha', '气象精灵', 'ウェザ', 'Normal Monster', 'Aqua', 'WATER', 3, 1000, 900, '操纵雨的精灵。召唤台风吹飞各种东西。'),
(2084239, 'Wetlands', '湿地草原', '湿地草原', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的水族·水属性·2星以下怪兽的攻击力上升1200。'),
(65961085, 'Wheel of Prophecy', '魔导兽士 鲁德', '魔導獣士 ルード', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2700, 1700, '这张卡用魔法师族怪兽的效果特殊召唤成功时，选择从游戏中除外的自己的名字带有「魔导书」的魔法卡任意数量才能发动。选择的卡回到卡组，剩下的名字带有「魔导书」的魔法卡回到墓地。「魔导兽士 鲁德」的效果1回合只能使用1次。'),
(60283232, 'Wheel Synchron', '轮同步士', 'ホイール・シンクロン', 'Tuner Monster', 'Machine', 'LIGHT', 5, 800, 1000, '这个卡名的②③的效果1回合各能使用1次。 ①：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ②：自己主要阶段才能发动。进行1只4星以下的怪兽的召唤。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。 ③：把墓地的这张卡除外，以自己场上1只同调怪兽为对象才能发动。那只怪兽的等级下降最多4星。'),
(51405049, 'Where Arf Thou?', '汪世一时！？', 'ワンチャン！？', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有1星怪兽存在的场合才能发动。从卡组把1只1星怪兽加入手卡，这个回合中，以下效果适用。 ●只要自己对这个效果加入手卡的怪兽或者那些同名卡的召唤不成功，结束阶段让自己受到2000伤害。'),
(91996584, 'Whiptail Crow', '鞭尾石像怪', 'ウィップテイル・ガーゴイル', 'Normal Monster', 'Fiend', 'DARK', 4, 1650, 1600, '使用鞭子一般长的尾巴，从空中发动攻击。'),
(53557529, 'Whirlwind Fur Hire', '飙风的空牙团', '飆風の空牙団', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合才能发动。从卡组把1只4星以下的「空牙团」怪兽特殊召唤。对方场上有怪兽2只以上存在的场合，可以再从卡组把1只「空牙团」怪兽特殊召唤。这个回合，自己不是「空牙团」怪兽不能特殊召唤。 ②：自己为让「空牙团」怪兽的效果发动而把手卡丢弃的场合，可以作为那1张卡的代替而把墓地的这张卡除外。'),
(91822647, 'Whirlwind of Gusto', '薰风的旋风', 'ガスタのつむじ風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有怪兽存在的场合才能发动。选择自己墓地存在的2只名字带有「薰风」的怪兽回到卡组。那之后，从自己卡组把1只守备力1000以下的名字带有「薰风」的怪兽特殊召唤。'),
(15090429, 'Whirlwind Prodigy', '暴风小僧', '暴風小僧', 'Effect Monster', 'Fairy', 'WIND', 4, 1500, 1600, '祭品召唤风属性怪兽的场合，这只怪兽1只作为2只份的祭品使用。'),
(93730409, 'Whirlwind Weasel', '真空鼬', '真空イタチ', 'Flip Effect Monster', 'Beast', 'WIND', 3, 500, 1500, '①：这张卡反转的场合发动。这个回合，对方不能把魔法·陷阱卡发动。'),
(89907227, 'White Aura Bihamut', '白斗气双头神龙', '白闘気双頭神龍', 'Synchro Monster', 'Fish', 'WATER', 10, 3300, 3000, '同调怪兽调整＋调整以外的怪兽1只以上 ①：自己回合这张卡同调召唤成功时才能发动。在自己场上把1只「神龙衍生物」（鱼族·水·10星·攻3300/守3000）守备表示特殊召唤。 ②：对方回合1次，自己场上没有衍生物的场合才能发动。在自己场上把1只「神龙衍生物」特殊召唤。 ③：这张卡被对方的效果破坏送去墓地的场合，若自己场上有「神龙衍生物」存在则能发动。这张卡守备表示特殊召唤。'),
(78229193, 'White Aura Dolphin', '白斗气海豚', '白闘気海豚', 'Synchro Monster', 'Fish', 'WATER', 6, 2400, 1000, '调整＋调整以外的怪兽1只以上 ①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成原本攻击力的一半。 ②：这张卡被对方破坏送去墓地的场合，把这张卡以外的自己墓地1只水属性怪兽除外才能发动。这张卡当作调整使用特殊召唤。'),
(63731062, 'White Aura Monoceros', '白斗气一角', '白闘気一角', 'Synchro Monster', 'Fish', 'WATER', 7, 2500, 1500, '水属性调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤成功时，以自己墓地1只鱼族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。 ②：这张卡被对方破坏送去墓地的场合，把这张卡以外的自己墓地1只水属性怪兽除外才能发动。这张卡当作调整使用特殊召唤。'),
(46956301, 'White Aura Porpoise', '白斗气砂滑', '白闘気砂滑', 'Synchro Monster', 'Fish', 'WATER', 6, 2000, 1300, '水属性调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己的手卡·墓地把1只4星以下的鱼族怪兽守备表示特殊召唤。那之后，可以把那1只同名怪兽从自己墓地特殊召唤。 ②：这张卡被对方破坏送去墓地的场合，从自己墓地把1只其他的水属性怪兽除外才能发动。这张卡当作调整使用特殊召唤。'),
(5614808, 'White Aura Whale', '白斗气白鲸', '白闘気白鯨', 'Synchro Monster', 'Fish', 'WATER', 8, 2800, 2000, '水属性调整＋调整以外的水属性怪兽1只以上 ①：这张卡同调召唤时才能发动。对方场上的攻击表示怪兽全部破坏。 ②：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ④：这张卡被对方破坏送去墓地的场合，从自己墓地把1只其他的水属性怪兽除外才能发动。这张卡当作调整使用特殊召唤。'),
(21579049, 'White Circle Reef', '白之循环礁', '白の循環礁', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只鱼族怪兽为对象才能发动。那只鱼族怪兽破坏，那1只同名怪兽从卡组加入手卡。这张卡的发动时自己场上有鱼族同调怪兽存在的场合，也能不加入手卡特殊召唤。 ②：把墓地的这张卡除外，以自己墓地2只鱼族同名怪兽为对象才能发动。那2只之内的1只回到卡组最下面，另1只特殊召唤。'),
(92409659, 'White Dolphin', '白海豚', 'ホワイト・ドルフィン', 'Normal Monster', 'Fish', 'WATER', 2, 500, 400, '头上有角的白色海豚。引起大浪攻击对方。'),
(99212922, 'White Dragon Ninja', '白龙忍者', '白竜の忍者', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2700, 1200, '这张卡特殊召唤的场合，用名字带有「忍法」的卡的效果才能特殊召唤。只要这张卡在场上表侧表示存在，自己场上的魔法·陷阱卡不会被卡的效果破坏。'),
(9786492, 'White Dragon Ritual', '白龙降临', '白竜降臨', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「白龙之圣骑士」的降临必需。 ①：等级合计直到4以上的自己的手卡·场上的怪兽解放，从手卡把「白龙之圣骑士」仪式召唤。'),
(99234526, 'White Dragon Wyverburster', '辉白龙 暴源翼龙', '輝白竜 ワイバースター', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1700, 1800, '这张卡不能通常召唤。从自己墓地把1只暗属性怪兽除外的场合才能特殊召唤。这个方法的「辉白龙 暴源翼龙」的特殊召唤1回合只能有1次。 ①：这张卡从场上送去墓地的场合才能发动。从卡组把1只「暗黑龙 坍缩星蛇」加入手卡。'),
(3557275, 'White Duston', '白尘小妖', 'ホワイト・ダストン', 'Normal Monster', 'Fiend', 'LIGHT', 1, NULL, 1000, '小恶魔尘妖一族的白色家伙。对身上连自己也惊讶的洁白好像灰常渍豪。'),
(18756904, 'White Elephant''s Gift', '马骨的报酬', '馬の骨の対価', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把效果怪兽以外的自己场上1只表侧表示怪兽送去墓地才能发动。自己从卡组抽2张。'),
(43487744, 'White Hole', '白洞', 'ホワイト・ホール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把「黑洞」发动时才能发动。自己场上存在的怪兽不会被那张「黑洞」的效果破坏。'),
(62487836, 'White Howling', '白之咆哮', '白の咆哮', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有水属性怪兽存在的场合，以对方墓地1张魔法卡为对象才能发动。那张卡除外，这个回合，对方场上的魔法卡的效果无效化。'),
(40352445, 'White Knight of Dogmatika', '凶教导之白骑士', '凶導の白騎士', 'Ritual Effect Monster', 'Spellcaster', 'LIGHT', 8, 500, 2500, '「凶导的福音」降临 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。 ②：对方把魔法·陷阱·怪兽的效果发动的场合才能发动。从自己的额外卡组把1只怪兽送去墓地，把对方的额外卡组确认，把那之内的1只怪兽送去墓地。这张卡的攻击力直到回合结束时上升送去墓地的怪兽的攻击力合计数值的一半。'),
(15150365, 'White Magical Hat', '白衣怪盗', '白い泥棒', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 1000, 700, '这张卡造成对方玩家基本分伤害的时候，对方随机丢弃1张卡。'),
(81383947, 'White Magician Pikeru', '白魔导士 绒儿', '白魔導士ピケル', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 1200, NULL, '在自己的准备阶段时，回复数值与自己场上存在的怪兽数量×400点等同的基本分。'),
(19885332, 'White Mirror', '白之水镜', '白の水鏡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只4星以下的鱼族怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以把原本卡名和这个效果特殊召唤的怪兽相同的1只怪兽从卡组加入手卡。'),
(32825095, 'White Moray', '白鳝', '白鱓', 'Effect Monster', 'Fish', 'WATER', 2, 600, 200, '①：这张卡召唤成功的回合，这张卡可以向对方直接攻击。 ②：这张卡从墓地的特殊召唤成功的场合才能发动。这个回合，这张卡当作调整使用。'),
(79473793, 'White Night Dragon', '青冰白夜龙', '青氷の白夜龍', 'Effect Monster', 'Dragon', 'WATER', 8, 3000, 2500, '①：这张卡为对象的魔法·陷阱卡发动时发动。那个发动无效并破坏。 ②：这张卡以外的自己的表侧表示怪兽被选择作为攻击对象时，把自己场上1张魔法·陷阱卡送去墓地才能发动。攻击对象转移为这张卡。'),
(20193924, 'White Night Queen', '白夜之女王', '白夜の女王', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2100, 800, '这张卡不能特殊召唤。1回合1次，可以把场上盖放的1张卡破坏。'),
(1571945, 'White Ninja', '白衣忍者', '白い忍者', 'Flip Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 800, '反转：破坏场上1只守备表示的怪兽。'),
(98024118, 'White Potan', '白面波波', 'ホワイトポータン', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, 200, '自己场上有调整表侧表示存在的场合，这张卡不会被战斗破坏。自己场上表侧表示存在的调整被战斗破坏送去墓地时，给与对方基本分500分伤害。'),
(91434208, 'White Reincarnation', '白之轮回', '白の輪廻', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，把持有把自身当作调整使用效果的1只鱼族怪兽从卡组加入手卡。 ②：1回合1次，自己的「白斗气」怪兽攻击的伤害步骤结束时才能发动。那只攻击怪兽只再1次可以继续攻击。 ③：1回合1次，从自己墓地有8星以上的鱼族同调怪兽特殊召唤的场合才能发动（伤害步骤也能发动）。对方场上的怪兽全部破坏。'),
(48654323, 'White Relic of Dogmatika', '凶教导之白圣骸', '凶導の白聖骸', 'Ritual Effect Monster', 'Spellcaster', 'LIGHT', 4, 500, 2500, '「凶导的葬列」降临 这个卡名的③的效果1回合只能使用1次。 ①：这张卡仪式召唤的场合，以场上2只表侧表示怪兽为对象才能发动。那之内1只的攻击力上升另1只的攻击力数值。 ②：8星以上的自己的「教导」怪兽不会被战斗破坏。 ③：从对方的额外卡组有怪兽特殊召唤的场合才能发动。把对方的额外卡组确认，那之内的1只怪兽送去墓地。'),
(84335863, 'White Rose Cloister', '白蔷薇回廊', '白薔薇の回廊', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合才能发动。从手卡把1只「蔷薇龙」怪兽或者植物族怪兽特殊召唤。 ②：自己抽卡阶段的抽卡前，宣言卡的种类（怪兽·魔法·陷阱）才能发动。自己卡组最上面的卡给双方确认，宣言的种类的卡的场合，这个回合中，以下效果适用。 ●自己场上的7星以上的同调怪兽的攻击力上升1000。'),
(12213463, 'White Rose Dragon', '白蔷薇龙', 'ホワイトローズ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 1200, 1000, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有龙族或植物族的调整存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤时才能发动。从自己的手卡·墓地把「白蔷薇龙」以外的1只「蔷薇龙」怪兽特殊召唤。 ③：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1只4星以上的植物族怪兽送去墓地。'),
(98684051, 'White Sardine', '白鰯', '白鰯', 'Effect Monster', 'Fish', 'WATER', 2, 800, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：从卡组把1只「白鰯」送去墓地才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能从额外卡组特殊召唤。 ②：这张卡从墓地特殊召唤的场合才能发动。这个回合，这张卡当作调整使用。'),
(11426487, 'White Steed of the Floral Knights', '花骑士团的白马', '花騎士団の白馬', 'Effect Monster', 'Beast', 'WIND', 6, 2400, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有2星以下的怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：对方怪兽的攻击宣言时，把墓地的这张卡除外，以自己场上1张卡为对象才能发动。那次攻击无效，作为对象的卡破坏。'),
(49930315, 'White Stingray', '白棘鲟', '白棘鱏', 'Effect Monster', 'Fish', 'WATER', 4, 1400, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把手卡1只水属性怪兽丢弃，从手卡特殊召唤。 ②：这张卡从墓地的特殊召唤成功的场合才能发动。这个回合，这张卡当作调整使用。'),
(52596406, 'White Sunfish', '白曼波', '白曼波', 'Effect Monster', 'Fish', 'WATER', 4, 1200, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以同名卡在自己场上存在的自己墓地1只4星以下的鱼族怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽特殊召唤。 ②：这张卡从墓地特殊召唤的场合才能发动。这个回合，这张卡当作调整使用。'),
(28348939, 'White Tiger Summoner', '白虎召唤士', '白虎の召喚士', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1000, 1700, '①：这张卡召唤成功时才能发动。从手卡把1只4星以下的通常怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的怪兽的攻击力·守备力上升100。'),
(49306994, 'White Veil', '白色面纱', '白のヴェール', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：装备怪兽进行战斗的攻击宣言时发动。对方场上的表侧表示的魔法·陷阱卡的效果直到伤害步骤结束时无效化。 ③：装备怪兽战斗破坏对方怪兽时才能发动。对方场上的魔法·陷阱卡全部破坏。 ④：魔法与陷阱区域的表侧表示的这张卡从场上离开时自己受到3000伤害。'),
(11067666, 'White Wing Magician', '白翼的魔术师', '白翼の魔術師', 'Pendulum Tuner Effect Monster', 'Spellcaster', 'WIND', 4, 1600, 1400, '这张卡在规则上也当作「同调龙」卡使用。灵摆召唤的这张卡被同调召唤使用的场合除外。'),
(73891874, 'White-Horned Dragon', '白角龙', 'ホワイト・ホーンズ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 6, 2200, 1400, '①：这张卡召唤·特殊召唤成功的场合，以对方墓地最多5张魔法卡为对象发动。那些卡除外，这张卡的攻击力上升那些除外的卡数量×300。'),
(31374201, 'Whitebeard, the Plunder Patroll Helm', '海造贼-白胡子机关士', '海造賊－白髭の機関士', 'Tuner Monster', 'Fiend', 'WATER', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：对方回合才能发动。把持有和对方的场上·墓地的怪兽的其中任意种相同属性的1只「海造贼」怪兽从额外卡组特殊召唤，自己场上的这张卡当作装备卡使用给那只怪兽装备。 ②：这张卡从手卡·怪兽区域送去墓地的场合才能发动。从卡组把「海造贼-白胡子机关士」以外的1只「海造贼」怪兽特殊召唤。这个回合，自己不是「海造贼」怪兽不能特殊召唤。'),
(63509474, 'Whitefish Salvage', '白之救济', '白の救済', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只鱼族怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡被对方的效果破坏送去墓地的场合才能发动。从卡组把1只鱼族怪兽加入手卡或特殊召唤。'),
(27103517, 'Wicked Acolyte Chilam Sabak', '邪神官 契伦·沙巴', '邪神官チラム・サバク', 'Effect Monster', 'Reptile', 'DARK', 8, 2500, NULL, '「邪神官 契伦·沙巴」的②的效果1回合只能使用1次。 ①：自己手卡是5张以上的场合，这张卡可以不用解放作召唤。 ②：这张卡被战斗破坏送去墓地时才能发动。这张卡从墓地守备表示特殊召唤。这个效果特殊召唤的这张卡当作调整使用。'),
(2957055, 'Wicked Dragon with the Ersatz Head', '魔头邪龙', '魔頭を持つ邪竜', 'Normal Monster', 'Dragon', 'WIND', 3, 900, 900, '长有两个头的龙。用两张嘴咬碎敌人。'),
(12965762, 'Wicked Plant Token', '死亡石斛', 'デス・デンドル', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(23440062, 'Wicked Rebirth', '邪恶苏生', 'ウィキッド・リボーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '支付800基本分，选择自己墓地存在的1只同调怪兽发动。选择的怪兽表侧攻击表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个回合不能攻击宣言。这张卡不在场上存在时，那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(81476402, 'Wicked Serpent Night Dragon', '恶夜龙 邪恶骑士龙', '邪悪龍エビルナイト・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2350, 2400, '这个卡名的①的效果1回合只能使用1次。 ①：把自己的手卡·场上1只暗属性怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：这张卡被战斗破坏时，以对方场上1只怪兽为对象才能发动。那只怪兽送去墓地。那之后，可以把这张卡特殊召唤。'),
(65810490, 'Wicked Token', '黄金邪神像', '黄金の邪神像', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(68427465, 'Wicked-Breaking Flamberge - Baou', '破邪之大剑-黄昏', '破邪の大剣－バオウ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '把手卡1张卡送去墓地装备。装备怪兽的攻击力上升500。这张卡装备的怪兽战斗破坏对方怪兽的场合，那只怪兽的效果无效化。'),
(42167046, 'Widespread Dud', '万能地雷未爆弹', 'グレイモヤ不発弾', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择场上表侧攻击表示存在的2只怪兽发动。选择的怪兽从场上离开时，这张卡破坏。这张卡破坏时，选择的怪兽破坏。'),
(77754944, 'Widespread Ruin', '万能地雷 阔剑式', '万能地雷グレイモヤ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方场上的表侧攻击表示怪兽之内攻击力最高的1只怪兽破坏。'),
(10705656, 'Widget Kid', '微件小子', 'ウィジェット・キッド', 'Effect Monster', 'Cyberse', 'EARTH', 3, 1500, 900, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把1只电子界族怪兽守备表示特殊召唤。'),
(39848658, 'Wight Reanimator', '白骨主宰者', 'ワイト・マスター', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己的「白骨王」向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：1回合1次，以自己墓地1只「白骨」或「白骨王」为对象才能发动。把1只「白骨」或者有那个卡名记述的怪兽从卡组送去墓地，作为对象的怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。'),
(6128460, 'Wightbaking', '白骨薯烤王', 'ワイトベイキング', 'Effect Monster', 'Zombie', 'DARK', 1, 300, 200, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡的卡名只要在墓地存在当作「白骨」使用。 ②：自己场上的3星以下的不死族怪兽被战斗·效果破坏的场合，可以作为代替把手卡的这张卡丢弃。 ③：这张卡被送去墓地的场合才能发动。从卡组把以下怪兽合计2只加入手卡（同名卡最多1张）。那之后，选1张手卡丢弃。 ●「白骨」 ●「白骨烤王」以外的有「白骨」的卡名记述的怪兽'),
(22970795, 'Wightlord', '白骨道君主', 'ワイトロード', 'Effect Monster', 'Zombie', 'LIGHT', 1, 300, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在墓地存在当作「白骨」使用。 ②：自己墓地有「白骨」或「白骨王」存在的场合，把手卡·场上的这张卡送去墓地才能发动。把最多有自己墓地的「白骨」「白骨王」数量的卡从自己卡组上面送去墓地。 ③：把墓地的这张卡除外，以自己墓地1只「白骨」或「白骨王」为对象才能发动。那只怪兽特殊召唤。'),
(22339232, 'Wightmare', '白骨梦魇', 'ワイトメア', 'Effect Monster', 'Zombie', 'DARK', 1, 300, 200, '这张卡的卡名只要在墓地存在当作「白骨」使用。此外，可以把这张卡从手卡丢弃从以下效果选择1个发动。 ●选择从游戏中除外的1只自己的「白骨」或者「白骨梦魇」回到自己墓地。 ●选择从游戏中除外的1只自己的「白骨夫人」或者「白骨王」在场上特殊召唤。'),
(57473560, 'Wightprince', '白骨皇子', 'ワイトプリンス', 'Effect Monster', 'Zombie', 'DARK', 1, NULL, NULL, '①：这张卡的卡名只要在墓地存在当作「白骨」使用。 ②：这张卡被送去墓地的场合才能发动。「白骨」「白骨夫人」各1只从手卡·卡组送去墓地。 ③：从自己墓地把2只其他的「白骨」和这张卡除外才能发动。从卡组把1只「白骨王」特殊召唤。'),
(90243945, 'Wightprincess', '白骨公主', 'ワイトプリンセス', 'Effect Monster', 'Zombie', 'LIGHT', 3, 1600, NULL, '①：这张卡的卡名只要在墓地存在当作「白骨」使用。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只「白骨王子」送去墓地。 ③：把自己的手卡·场上的这张卡送去墓地才能发动。场上的全部怪兽的攻击力·守备力直到回合结束时下降那等级或者阶级×300。这个效果在对方回合也能发动。'),
(68815401, 'Wild Fire', '狂焰', 'クレイジー・ファイヤー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '支付500基本分。自己场上表侧表示存在的名字带有「烈焰加农炮」的卡破坏，场上的怪兽全部破坏。之后，在自己场上攻击表示特殊召唤1只「狂焰衍生物」（炎族·炎·3星·攻/守1000）。这个回合自己怪兽不能攻击。'),
(68815402, 'Wild Fire Token', '狂焰', 'クレイジー・ファイヤー', 'Token', 'Pyro', NULL, NULL, NULL, NULL, NULL),
(61166988, 'Wild Nature''s Release', '野性解放', '野性解放', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上1只兽族·兽战士族怪兽才能发动。选择的兽族·兽战士族怪兽的攻击力上升那只怪兽的守备力数值。受到这个效果影响的怪兽在结束阶段时破坏。'),
(47766694, 'Wild Tornado', '荒野的大龙卷', '荒野の大竜巻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以魔法与陷阱区域1张表侧表示的卡为对象才能发动。那张表侧表示的卡破坏。那之后，破坏的卡的控制者可以从手卡把1张魔法·陷阱卡盖放。 ②：盖放的这张卡被破坏送去墓地的场合，以场上1张表侧表示的卡为对象发动。那张表侧表示的卡破坏。'),
(64178424, 'Will of the Salamangreat', '转生炎兽之意志', '転生炎獣の意志', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己主要阶段才能发动。从自己的手卡·墓地选1只「转生炎兽」怪兽特殊召唤。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以用和自身同名的怪兽为素材作连接召唤的自己场上1只「转生炎兽」连接怪兽为对象才能发动。从自己的手卡·墓地选最多有那只怪兽的连接标记数量的「转生炎兽」怪兽守备表示特殊召唤。'),
(92391084, 'Wilmee', '威尔米', 'ウィルミー', 'Normal Monster', 'Beast', 'EARTH', 4, 1000, 1200, '相当凶暴的兔子。以锐利的钩爪血祭对方。'),
(99865167, 'Wind Effigy', '风构体', 'ウィンドフレーム', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1800, 200, '风属性的通常怪兽祭品召唤的场合，这1只怪兽可以作为2只的数量的祭品。'),
(98506199, 'Wind Pegasus @Ignister', '风飞马＠伊格尼斯者', 'ウィンドペガサス＠イグニスター', 'Synchro Monster', 'Cyberse', 'WIND', 7, 2300, 1500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。选最多有自己场上的「@火灵天星」怪兽数量的对方场上的魔法·陷阱卡破坏。 ②：这张卡在场上·墓地存在的状态，这张卡以外的自己场上的卡被战斗或者对方的效果破坏的场合，把这张卡除外，以对方场上1张卡为对象才能发动。那张卡回到持有者卡组。'),
(39016067, 'Wind Unicorn Parallel, the Dracoslayer', '龙剑士 乘风独角麒麟 别型', '竜剣士ウィンドユニコーンP', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 6, 2000, 2000, '这个卡名的②的怪兽效果1回合只能使用1次。 ①：只要灵摆召唤的这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：自己·对方回合，以自己场上1张灵摆怪兽卡和对方场上1张卡为对象才能发动。那些卡回到手卡。'),
(77334267, 'Wind-Up Arsenal Zenmaioh', '弹簧装攻 发条王', '発条装攻ゼンマイオー', 'XYZ Monster', 'Machine', 'WIND', 5, 2600, 1900, '5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以场上2张里侧表示卡为对象才能发动。那些卡破坏。'),
(42328171, 'Wind-Up Bat', '发条蝙蝠', 'ゼンマイバット', 'Effect Monster', 'Machine', 'WIND', 1, 300, 350, '自己的主要阶段时才能发动。把自己场上表侧攻击表示存在的这张卡变更为表侧守备表示，选择自己墓地存在的1只名字带有「发条」的怪兽加入手卡。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(81122844, 'Wind-Up Carrier Zenmaity', '发条空母 发条巨舰', '発条空母ゼンマイティ', 'XYZ Monster', 'Machine', 'WATER', 3, 1500, 1500, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从手卡·卡组把1只「发条」怪兽特殊召唤。 ②：场上的表侧表示的「发条」怪兽被战斗以外破坏送去自己墓地时，把这张卡1个超量素材取除，以那1只「发条」怪兽为对象才能发动。那只怪兽加入手卡。'),
(12076263, 'Wind-Up Dog', '发条犬', 'ゼンマイドッグ', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 900, '自己的主要阶段时才能发动。直到结束阶段时这张卡的等级上升2星，攻击力上升600。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(95714077, 'Wind-Up Factory', '发条制造业', 'ゼンマイマニュファクチャ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '名字带有「发条」的怪兽的效果发动的场合，可以从自己卡组把1只4星以下的名字带有「发条」的怪兽加入手卡。这个效果1回合只能使用1次。'),
(93451636, 'Wind-Up Honeybee', '发条蜜蜂', 'ゼンマイハニー', 'Effect Monster', 'Insect', 'EARTH', 1, 100, 300, '这张卡被战斗破坏送去墓地时，可以从卡组把1只4星以下的名字带有「发条」的怪兽特殊召唤。'),
(16923472, 'Wind-Up Hunter', '发条猎人', 'ゼンマイハンター', 'Effect Monster', 'Beast-Warrior', 'DARK', 3, 1600, 500, '自己的主要阶段时，把「发条猎人」以外的自己场上表侧表示存在的1只名字带有「发条」的怪兽解放才能发动。对方手卡随机1张送去墓地。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(85682655, 'Wind-Up Juggler', '发条杂耍人', 'ゼンマイジャグラー', 'Effect Monster', 'Psychic', 'WIND', 4, 1700, 1000, '这张卡和对方怪兽进行战斗的场合，可以把那只对方怪兽在伤害计算后破坏。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(25716180, 'Wind-Up Kitten', '发条猫咪', 'ゼンマイニャンコ', 'Effect Monster', 'Beast', 'EARTH', 2, 800, 500, '自己的主要阶段时才能发动。选择对方场上存在的1只怪兽回到持有者手卡。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(80538728, 'Wind-Up Knight', '发条骑士', 'ゼンマイナイト', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1200, '自己场上表侧表示存在的名字带有「发条」的怪兽被选择作为攻击对象时，可以把那只怪兽的攻击无效。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(59297550, 'Wind-Up Magician', '发条魔术师', 'ゼンマイマジシャン', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 600, 1800, '「发条魔术师」以外的名字带有「发条」的怪兽的效果发动的场合，可以从自己卡组把1只名字带有「发条」的4星以下的怪兽表侧守备表示特殊召唤。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(42874792, 'Wind-Up Rabbit', '发条兔', 'ゼンマイラビット', 'Effect Monster', 'Beast-Warrior', 'EARTH', 3, 1400, 600, '选择自己场上1只名字带有「发条」的怪兽才能发动。选择的怪兽直到下次的自己的准备阶段时从游戏中除外。这个效果在对方回合也能发动。此外，这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(57962537, 'Wind-Up Rat', '发条鼠', 'ゼンマイネズミ', 'Effect Monster', 'Beast', 'EARTH', 3, 600, 600, '自己的主要阶段时才能发动。把自己场上表侧攻击表示存在的这张卡变更为表侧守备表示，选择自己墓地1只名字带有「发条」的怪兽表侧守备表示特殊召唤。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(25484449, 'Wind-Up Shark', '发条鲨', 'ゼンマイシャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 1300, '①：自己场上有「发条」怪兽召唤·特殊召唤时才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，可以从以下效果选择1个发动。 ●这张卡的等级直到回合结束时上升1星。 ●这张卡的等级直到回合结束时下降1星。'),
(58475908, 'Wind-Up Snail', '发条蜗牛', 'ゼンマイマイ', 'Effect Monster', 'Aqua', 'WATER', 2, 100, 2000, '自己的主要阶段时，可以选择场上盖放的1张卡回到持有者手卡。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(12299841, 'Wind-Up Soldier', '发条士兵', 'ゼンマイソルジャー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1200, '自己的主要阶段时才能发动。直到结束阶段时这张卡的等级上升1星，攻击力上升400。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(53540729, 'Wind-Up Warrior', '发条战士', 'ゼンマイウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 1800, '选择自己场上表侧表示存在的1只名字带有「发条」的怪兽才能发动。直到结束阶段时选择的1只怪兽的等级上升1星，攻击力上升600。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(78156759, 'Wind-Up Zenmaines', '发条机雷 发条雷', '発条機雷ゼンマイン', 'XYZ Monster', 'Machine', 'FIRE', 3, 1500, 2100, '3星怪兽×2 场上的这张卡被破坏的场合，可以作为代替把这张卡1个超量素材取除。这个效果适用的回合的结束阶段时1次，选择场上1张卡破坏。'),
(1735088, 'Wind-Up Zenmaintenance', '发条修补 发条微机', '発条補修ゼンマイコン', 'Link Monster', 'Machine', 'LIGHT', NULL, 1800, NULL, '「发条」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「发条」卡加入手卡。 ②：把自己场上1只表侧表示的「发条」怪兽里侧表示除外才能发动。把1只和那只是同名的怪兽从卡组特殊召唤。 ③：这张卡被破坏送去墓地的场合，以自己场上1只「发条」超量怪兽为对象才能发动。把这张卡在那只怪兽下面重叠作为超量素材。'),
(68597372, 'Wind-Up Zenmaister', '发条机甲 发条大师', '発条機甲ゼンマイスター', 'XYZ Monster', 'Machine', 'EARTH', 4, 1900, 1500, '4星怪兽×2 这张卡的攻击力上升这张卡的超量素材数量×300的数值。1回合1次，把这张卡1个超量素材取除，选择自己场上表侧表示存在的1只怪兽才能发动。选择的怪兽变成里侧守备表示。这个回合的结束阶段时，选择的怪兽变成表侧攻击表示。'),
(54455435, 'Winda, Priestess of Gusto', '薰风的巫女 薇茵妲', 'ガスタの巫女 ウィンダ', 'Effect Monster', 'Psychic', 'WIND', 2, 1000, 400, '这张卡被对方怪兽的攻击破坏送去墓地时，可以从自己卡组把1只名字带有「薰风」的调整特殊召唤。'),
(27944249, 'Windaar, Sage of Gusto', '薰风的贤者 温达尔', 'ガスタの賢者 ウィンダール', 'Effect Monster', 'Psychic', 'WIND', 6, 2000, 1000, '这张卡战斗破坏怪兽送去墓地时，可以把自己墓地存在的1只3星以下的名字带有「薰风」的怪兽表侧守备表示特殊召唤。'),
(43925870, 'Windmill Genex', '风场次代机', 'ウィンドファーム・ジェネクス', 'Synchro Monster', 'Machine', 'WIND', 7, 2000, 1600, '「次世代控制员」＋调整以外的风属性怪兽1只以上 ①：这张卡的攻击力上升场上的里侧表示的魔法·陷阱卡数量×300。 ②：把1张手卡送去墓地，以场上1张里侧表示的魔法·陷阱卡为对象才能发动。那张里侧表示卡破坏。'),
(53027855, 'Windrose the Elemental Lord', '风灵神 温德罗斯', '風霊神ウィンドローズ', 'Effect Monster', 'Winged Beast', 'WIND', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的风属性怪兽是5只的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合发动。对方场上的魔法·陷阱卡全部破坏。 ②：表侧表示的这张卡从场上离开的场合，下次的自己回合的战斗阶段跳过。'),
(37301660, 'WINDS OF VICTORY', '胜利之风', 'WINDS OF VICTORY', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升300，变成风属性。'),
(17197110, 'Winds Over the Ice Barrier', '抵达冰结界的晴岚', '氷結界に至る晴嵐', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的「冰结界」怪兽任意数量解放才能发动。把解放数量的4星以下的「冰结界」怪兽从卡组特殊召唤（同名卡最多1张）。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己的墓地·除外状态的1只「冰结界」怪兽为对象才能发动。那只怪兽加入手卡。'),
(59744639, 'Windstorm of Etaqua', '伊塔库亚的暴风', 'イタクァの暴風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上的全部表侧表示怪兽的表示形式变更。'),
(84851250, 'Windwitch - Blizzard Bell', '风魔女－暴雪铃', 'WW－ブリザード・ベル', 'Tuner Monster', 'Spellcaster', 'WIND', 5, 1800, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽不存在的场合或者只有「风魔女」怪兽的场合，这张卡可以不用解放作召唤。 ②：自己场上有「风魔女-雪暴铃」以外的「风魔女」怪兽存在的场合，对方主要阶段，把手卡·场上的这张卡送去墓地才能发动。给与对方500伤害。'),
(25793414, 'Windwitch - Crystal Bell', '风魔女－水晶铃', 'WW－クリスタル・ベル', 'Fusion Monster', 'Spellcaster', 'WIND', 8, 2800, 2400, '「风魔女-冬铃」＋「风魔女」怪兽 「风魔女-水晶钟」的①②的效果1回合各能使用1次。 ①：以自己或者对方的墓地1只怪兽为对象才能发动。直到结束阶段，这张卡当作和那只怪兽同名卡使用，得到相同效果。 ②：这张卡被对方破坏送去墓地的场合，以自己墓地1只「风魔女-冬铃」和1只4星以下的「风魔女」怪兽为对象才能发动。那些怪兽特殊召唤。'),
(73667937, 'Windwitch - Diamond Bell', '风魔女－钻铃', 'WW－ダイヤモンド・ベル', 'Synchro Monster', 'Spellcaster', 'WIND', 8, 2800, 2400, '调整＋调整以外的风属性怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤成功的场合，以自己墓地1只「风魔女」怪兽为对象才能发动。给与对方那只怪兽的攻击力一半数值的伤害。 ②：1回合1次，对方因战斗·效果受到伤害的场合，以场上1张卡为对象才能发动。那张卡破坏。这张卡是已只用「风魔女」怪兽为素材作同调召唤的场合，这个效果1回合可以使用最多2次。'),
(20246864, 'Windwitch - Freeze Bell', '风魔女－冻铃', 'WW－フリーズ・ベル', 'Effect Monster', 'Spellcaster', 'WIND', 3, 1200, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上的怪兽只有「风魔女」怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，自己主要阶段才能发动。这张卡的等级上升1星。 ③：用这张卡为同调素材把风属性同调怪兽同调召唤的场合，那只同调怪兽不会被战斗破坏。'),
(71007216, 'Windwitch - Glass Bell', '风魔女－玻璃铃', 'WW－グラス・ベル', 'Tuner Monster', 'Spellcaster', 'WIND', 4, 1500, 1500, '「风魔女-玻璃铃」的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「风魔女-玻璃铃」以外的1只「风魔女」怪兽加入手卡。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(43722862, 'Windwitch - Ice Bell', '风魔女－冰铃', 'WW－アイス・ベル', 'Effect Monster', 'Spellcaster', 'WIND', 3, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1只「风魔女」怪兽特殊召唤。这个效果从卡组特殊召唤的怪兽不能解放，这个效果发动的回合，自己不是5星以上的风属性怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。给与对方500伤害。'),
(70117860, 'Windwitch - Snow Bell', '风魔女－雪铃', 'WW－スノウ・ベル', 'Tuner Monster', 'Spellcaster', 'WIND', 1, 100, 100, '①：自己场上有风属性怪兽2只以上存在，没有风属性以外的怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：用这张卡为同调素材把风属性同调怪兽同调召唤的场合，那只同调怪兽不会被对方的效果破坏。'),
(14577226, 'Windwitch - Winter Bell', '风魔女－冬铃', 'WW－ウィンター・ベル', 'Synchro Monster', 'Spellcaster', 'WIND', 7, 2400, 2000, '调整＋调整以外的风属性怪兽1只以上 「风魔女-冬铃」的①②的效果1回合各能使用1次。 ①：以自己墓地1只「风魔女」怪兽为对象才能发动。给与对方那只怪兽的等级×200伤害。 ②：自己·对方的战斗阶段以自己场上1只「风魔女」怪兽为对象才能发动。把持有那只怪兽的等级以下的等级的1只怪兽从手卡特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(96156729, 'Windwitch Chimes', '风魔女之铃音', 'WWの鈴音', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是风属性怪兽不能特殊召唤。 ①：以自己场上1只「风魔女」怪兽为对象才能发动。和那只怪兽卡名不同的1只「风魔女」怪兽从卡组守备表示特殊召唤。'),
(47319141, 'Wing Eagle', '飞鹰', 'ウイング・イーグル', 'Normal Monster', 'Winged Beast', 'WIND', 5, 1800, 1500, '从高空寻找猎物，一旦看上绝不让其逃走。'),
(98582704, 'Wing Egg Elf', '翼蛋精灵', 'ウィング・エッグ・エルフ', 'Normal Monster', 'Fairy', 'LIGHT', 3, 500, 1300, '被蛋壳包住的天使。用巨大翅膀守备攻击。'),
(8843569, 'Wing Requital', '翼之报恩', '翼の恩返し', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽只有鸟兽族怪兽并有原本卡名不同的怪兽2只以上的场合，支付600基本分才能发动。自己从卡组抽2张。'),
(39175982, 'Winged Cleaver', '暗黑杀手', 'ダークキラー', 'Normal Monster', 'Insect', 'EARTH', 2, 700, 700, '挥动如镰刀般发达的手臂进行攻击。'),
(87796900, 'Winged Dragon, Guardian of the Fortress #1', '护城翼龙', '砦を守る翼竜', 'Normal Monster', 'Dragon', 'WIND', 4, 1400, 1200, '守护山上城寨的龙。从天空俯冲下来攻击敌人。'),
(57405307, 'Winged Dragon, Guardian of the Fortress #2', '翼龙', 'ワイバーン', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1200, 1000, '挥动翅膀卷起强有力的龙卷风。'),
(42418084, 'Winged Egg of New Life', '诞生的天使', '誕生の天使', 'Normal Monster', 'Fairy', 'LIGHT', 5, 1400, 1700, '据说它能知道女性腹部是否存在着生命。'),
(57116033, 'Winged Kuriboh', '羽翼库里波', 'ハネクリボー', 'Effect Monster', 'Fairy', 'LIGHT', 1, 300, 200, '①：场上的这张卡被破坏送去墓地的场合发动。这个回合，自己受到的战斗伤害变成0。'),
(98585345, 'Winged Kuriboh LV10', '羽翼栗子球 LV10', 'ハネクリボー LV１０', 'Effect Monster', 'Fairy', 'LIGHT', 10, 300, 200, '这张卡不能通常召唤。这张卡只能通过「进化之翼」的效果特殊召唤。可以把自己场上表侧表示存在的这张卡作祭品，对方场上攻击表示的怪兽全部破坏，给与对方基本分破坏怪兽的原本的攻击力合计的数值的伤害。这个效果在对方战斗阶段中才能发动。'),
(48486809, 'Winged Kuriboh LV6', '羽翼库里波 LV6', 'ハネクリボー LV６', 'Effect Monster', 'Fairy', 'LIGHT', 6, 300, 200, '这个卡名在规则上也当作「元素英雄」卡、「至爱」卡使用。这张卡不能通常召唤。「羽翼栗子球 LV6」1回合1次在把自己的手卡·场上（表侧表示）·墓地1只「元素英雄」融合怪兽或「羽翼栗子球」除外的场合才能从手卡·墓地特殊召唤。 ①：对方怪兽的攻击宣言时或者对方把场上的怪兽的效果发动时，把这张卡解放才能发动。那1只怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(33776734, 'Winged Kuriboh LV9', '羽翼栗子球 LV9', 'ハネクリボー LV９', 'Effect Monster', 'Fairy', 'LIGHT', 9, -1, -1, '当有连锁发生时，可以从自己手卡把这张卡特殊召唤。只要这张卡在自己场上表侧表示存在，双方发动的魔法卡不送去墓地从游戏中除外。这张卡的攻击力·守备力变成对方墓地存在的魔法卡数量×500的数值。「羽翼栗子球 LV9」在自己场上只能有1张表侧表示存在。'),
(89258225, 'Winged Minion', '哈·迪斯的使魔', 'ハ・デスの使い魔', 'Effect Monster', 'Fiend', 'DARK', 2, 700, 700, '这张卡做祭品。选择场上表侧表示存在的1只恶魔族怪兽。只要那只怪兽表侧表示在场上存在，攻击力·守备力上升700。'),
(18430390, 'Winged Rhynos', '飞翼犀牛', 'ウィングド・ライノ', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1800, 500, '陷阱卡发动时可以发动。场上表侧表示存在的这张卡回到持有者手卡。'),
(87523462, 'Winged Sage Falcos', '有翼贤者 法尔科斯', '有翼賢者ファルコス', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1700, 1200, '被这张卡战斗破坏并将送去墓地的对方表侧攻击表示的怪兽，可以把其放回对方卡组最上面。'),
(82190203, 'Wings of Light', '光翼之龙', '光翼の竜', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段才能发动。从卡组把1只「霸王眷龙」灵摆怪兽或「霸王门」灵摆怪兽加入手卡。自己场上有「霸王龙 扎克」存在的场合，也能不加入手卡特殊召唤。'),
(92944626, 'Wings of Wicked Flame', '邪炎之翼', '邪炎の翼', 'Normal Monster', 'Pyro', 'FIRE', 2, 700, 600, '原形是红黑色燃烧着的翅膀。从全身喷出火焰进行攻击。'),
(10132124, 'Wingtortoise', '翼龟', 'ウイングトータス', 'Effect Monster', 'Aqua', 'WIND', 3, 1500, 1400, '自己场上表侧表示存在的鱼族·海龙族·水族怪兽从游戏中除外时，这张卡可以从手卡或者自己墓地特殊召唤。'),
(31447217, 'Wingweaver', '织翼者', '翼を織りなす者', 'Normal Monster', 'Fairy', 'LIGHT', 7, 2750, 2400, '六翼天使操纵着人的自由和希望。'),
(34507039, 'Wiretap', '发讯追踪', 'ギャクタン', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：陷阱卡发动时才能发动。那个发动无效，那张卡回到卡组。'),
(72714461, 'Wisdom-Eye Magician', '慧眼的魔术师', '慧眼の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1500, '①：把这张卡从手卡丢弃，以自己的灵摆区域1张灵摆刻度和原本数值不同的卡为对象才能发动。那张卡的灵摆刻度直到回合结束时变成原本数值。'),
(35262428, 'Wiseman''s Chalice', '贤者的圣杯', '賢者の聖杯', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有怪兽存在的场合，选择对方墓地存在的1只怪兽才能发动。选择的怪兽在自己场上特殊召唤。这个回合的结束阶段时，这个效果特殊召唤的怪兽的控制权转移给对方。此外，这个效果特殊召唤的怪兽不能解放，也不能作为同调素材。'),
(64583600, 'Wish Dragon', '祈愿龙', 'ウィッシュ・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 2, 700, 100, '这个卡名的效果1回合只能使用1次。 ①：把这张卡解放才能发动。在自己场上把2只「龙衍生物」（龙族·地·1星·攻/守0）特殊召唤。这个效果的发动后，直到回合结束时自己不是5星以上的龙族怪兽不能从额外卡组特殊召唤。'),
(80326401, 'Wishes for Eyes of Blue', '青之眼的祈祷', '青き眼の祈り', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。除「青色眼睛的祈祷」外的1张有「青眼白龙」的卡名记述的魔法·陷阱卡和1只光属性·1星调整从卡组加入手卡。 ②：把墓地的这张卡除外，以自己场上1只「青眼白龙」为对象才能发动。从额外卡组把1只「青眼」怪兽当作攻击力上升400的装备魔法卡使用给作为对象的怪兽装备。'),
(75946257, 'Witch Doctor of Chaos', '混沌咒术师', '混沌の呪術師', 'Flip Effect Monster', 'Spellcaster', 'DARK', 2, 500, 500, '反转：从自己或对方的墓地里选择1张怪兽卡，将被选择的卡从游戏中除外。'),
(30525991, 'Witch Doctor of Sparta', '斯巴达咒术师', 'スパルタクァの呪術師', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 400, 2000, '这张卡在场上表侧表示存在的场合，每次怪兽从卡组特殊召唤，给与对方基本分500分伤害。'),
(78010363, 'Witch of the Black Forest', '黑森林女巫', '黒き森のウィッチ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1100, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡从场上送去墓地的场合发动。从卡组把1只守备力1500以下的怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的卡以及那些同名卡的效果发动。'),
(17720747, 'Witch of the Black Rose', '黑蔷薇之魔女', '黒薔薇の魔女', 'Tuner Monster', 'Spellcaster', 'DARK', 4, 1700, 1200, '这张卡不能特殊召唤。 ①：自己场上没有其他卡存在，这张卡召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是怪兽以外的场合，那张卡送去墓地，这张卡破坏。'),
(4398189, 'Witch of the White Forest', '白森的魔女', '白き森の魔女', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「白森林」怪兽加入手卡。那个场合，这个回合，自己不能把暗属性怪兽从额外卡组特殊召唤。 ②：自己的「白森林」怪兽在1回合各有1次不会被战斗破坏。 ③：以自己场上1只「白森林」怪兽为对象才能发动。这个回合，那只怪兽当作调整使用。'),
(80741828, 'Witch''s Apprentice', '见习魔女', '見習い魔女', 'Effect Monster', 'Spellcaster', 'DARK', 2, 550, 500, '①：场上的暗属性怪兽的攻击力上升500，光属性怪兽的攻击力下降400。'),
(36458063, 'Witch''s Strike', '魔女的一击', '魔女の一撃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把怪兽的召唤·特殊召唤无效的场合或者对方把魔法·陷阱·怪兽的效果的发动无效的场合才能发动。对方的手卡·场上的卡全部破坏。'),
(83289866, 'Witchcrafter Bystreet', '魔女工艺・窄巷', 'ウィッチクラフト・バイストリート', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：自己场上的「魔女术」怪兽在1回合各有1次不会被战斗·效果破坏。 ②：自己场上的「魔女术」怪兽为让效果发动而把手卡丢弃的场合，可以作为代替把这张卡送去墓地。 ③：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡在自己的魔法与陷阱区域表侧表示放置。'),
(10805153, 'Witchcrafter Collaboration', '魔女工艺・协作', 'ウィッチクラフト・コラボレーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「魔女术」怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击，那只怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡加入手卡。'),
(35098357, 'Witchcrafter Confusion Confession', '魔女工艺・混乱结合', 'ウィッチクラフト・コンフュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的手卡·场上把融合怪兽卡决定的包含「魔女术」怪兽的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡加入手卡。'),
(57916305, 'Witchcrafter Creation', '魔女工艺・创生', 'ウィッチクラフト・クリエイション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只「魔女术」怪兽加入手卡。 ②：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡加入手卡。'),
(56894757, 'Witchcrafter Draping', '魔女工艺・立体裁剪', 'ウィッチクラフト・ドレーピング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以最多有自己场上的「魔女术」怪兽数量的对方场上的魔法·陷阱卡为对象才能发动。那些卡回到持有者手卡。 ②：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡加入手卡。'),
(58139997, 'Witchcrafter Edel', '魔女工艺・珠宝匠安黛尔', 'ウィッチクラフト・エーデル', 'Effect Monster', 'Spellcaster', 'LIGHT', 5, 2000, 2300, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法卡才能发动。从手卡把「魔女术工匠·宝石女巫」以外的1只「魔女术」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：把这张卡解放，以自己墓地1只「魔女术工匠·宝石女巫」以外的魔法师族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(64756282, 'Witchcrafter Genni', '魔女工艺・万能杰妮', 'ウィッチクラフト・ジェニー', 'Effect Monster', 'Spellcaster', 'WIND', 1, 300, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·万能杰妮」以外的1只「魔女术」怪兽特殊召唤。 ②：从自己墓地把这张卡和1张「魔女术」魔法卡除外才能发动。这个效果变成和那张魔法卡发动时的效果相同。'),
(71074418, 'Witchcrafter Golem Aruru', '魔女工艺魔像・阿鲁鲁', 'ウィッチクラフトゴーレム・アルル', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 2800, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在，自己场上的魔法师族怪兽成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时，以对方场上1张卡或者自己墓地1张「魔女术」魔法卡为对象才能发动。这张卡特殊召唤，那张卡回到持有者手卡。 ②：对方准备阶段发动。这张卡回到持有者手卡。'),
(84523092, 'Witchcrafter Haine', '魔女工艺・裁缝海涅', 'ウィッチクラフト・ハイネ', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2400, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己场上的其他的魔法师族怪兽不会成为对方的效果的对象。 ②：从手卡丢弃1张魔法卡，以对方场上1张表侧表示的卡为对象才能发动。那张卡破坏。这个效果在对方回合也能发动。'),
(83301414, 'Witchcrafter Holiday', '魔女工艺・怠工', 'ウィッチクラフト・サボタージュ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己墓地1只「魔女术」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡加入手卡。'),
(21522601, 'Witchcrafter Madame Verre', '魔女工艺掌门・玻璃匠薇儿', 'ウィッチクラフトマスター・ヴェール', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 1000, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的魔法师族怪兽和对方怪兽进行战斗的伤害计算时才能发动。卡名不同的手卡的魔法卡任意数量给对方观看，那只自己怪兽的攻击力·守备力直到回合结束时上升给人观看的数量×1000。 ②：自己·对方回合，从手卡丢弃1张魔法卡才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效。'),
(55072170, 'Witchcrafter Masterpiece', '魔女工艺・掌门杰作', 'ウィッチクラフト・マスターピース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「魔女术」怪兽存在的场合，以自己或者对方的墓地1张魔法卡为对象才能发动。把1张那张卡的同名卡从自己卡组加入手卡。 ②：从自己墓地把这张卡和魔法卡任意数量除外才能发动。和除外的魔法卡数量相同等级的1只「魔女术」怪兽从卡组特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(94553671, 'Witchcrafter Patronus', '魔女工艺・守护圣者', 'ウィッチクラフト・パトローナス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地的怪兽以及除外的自己怪兽之中以1只魔法师族怪兽为对象才能发动。那只怪兽回到卡组，从卡组把1张「魔女术」魔法卡加入手卡。 ②：把墓地的这张卡除外，以除外的自己的「魔女术」魔法卡任意数量为对象才能发动（同名卡最多1张）。那些卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(95245544, 'Witchcrafter Pittore', '魔女工艺・涂装皮特莱', 'ウィッチクラフト・ピットレ', 'Effect Monster', 'Spellcaster', 'WATER', 3, 1000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·绘画女巫」以外的1只「魔女术」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。自己从卡组抽1张，那之后从手卡选1张「魔女术」卡送去墓地。手卡没有「魔女术」卡的场合，手卡全部除外。'),
(59851535, 'Witchcrafter Potterie', '魔女工艺・陶艺玻特丽', 'ウィッチクラフト・ポトリー', 'Effect Monster', 'Spellcaster', 'EARTH', 2, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·陶器女巫」以外的1只「魔女术」怪兽特殊召唤。 ②：自己手卡是0张的场合，把墓地的这张卡除外，以自己墓地1张「魔女术」卡为对象才能发动。那张卡加入手卡。'),
(21744288, 'Witchcrafter Schmietta', '魔女工艺・铁匠舒蜜塔', 'ウィッチクラフト・シュミッタ', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1800, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡解放，从手卡丢弃1张魔法卡才能发动。从卡组把「魔女术工匠·锻造女巫」以外的1只「魔女术」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把「魔女术工匠·锻造女巫」以外的1张「魔女术」卡送去墓地。'),
(19673561, 'Witchcrafter Scroll', '魔女工艺・羊皮纸卷', 'ウィッチクラフト・スクロール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：1回合1次，自己的魔法师族怪兽战斗破坏怪兽时才能发动。自己从卡组抽1张。 ②：自己场上的「魔女术」怪兽为让效果发动而把手卡丢弃的场合，可以作为代替把这张卡送去墓地。 ③：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡在自己的魔法与陷阱区域表侧表示放置。'),
(70226289, 'Witchcrafter Unveiling', '魔女工艺・演示', 'ウィッチクラフト・デモンストレーション', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡把1只「魔女术」怪兽特殊召唤。这个效果特殊召唤的回合，对方不能对应自己的魔法师族怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。 ②：这张卡在墓地存在，自己场上有「魔女术」怪兽存在的场合，自己结束阶段才能发动。这张卡加入手卡。'),
(9603252, 'Witchcrafter Vice-Madame', '魔女工艺・代理掌门', 'ウィッチクラフト・バイスマスター', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 2700, 2800, '「魔女术」怪兽＋魔法师族怪兽 ①：融合怪兽以外的魔法师族怪兽或者魔法卡的效果发动时，可以从以下效果选择1个发动。「魔女术代理师傅」的以下效果1回合各能选择1次。 ●选场上1张卡破坏。 ●从手卡·卡组把1只6星以下的「魔女术」怪兽特殊召唤。 ●从自己墓地选1张「魔女术」魔法·陷阱卡加入手卡。'),
(36304921, 'Witty Phantom', '魔人 死亡撒旦', '魔人デスサタン', 'Normal Monster', 'Fiend', 'DARK', 4, 1400, 1300, '穿着融入黑暗的黑色燕尾服，操纵着死亡的恶魔。'),
(1527418, 'Wiz, Sage Fur Hire', '空牙团的睿智 薇滋', '空牙団の叡智 ウィズ', 'Effect Monster', 'Spellcaster', 'WATER', 7, 1600, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。自己回复「空牙团的睿智 薇兹」以外的自己场上的「空牙团」怪兽种类×500基本分。 ②：对方把魔法·陷阱卡的效果发动时，从手卡丢弃1张「空牙团」卡才能发动。那个发动无效。'),
(3723262, 'Wizard @Ignister', '男巫＠伊格尼斯者', 'ウィザード＠イグニスター', 'Effect Monster', 'Cyberse', 'DARK', 4, 1800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的电子界族怪兽在自己场上存在的场合，以自己墓地1只电子界族·暗属性怪兽为对象才能发动。那只怪兽和手卡的这张卡守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。 ②：把场上·墓地的这张卡除外，以对方场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(2602411, 'Wizard Buster Destruction Sword', '破坏剑-魔法破坏之剑', '破壊剣－ウィザードバスターブレード', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1200, 900, '①：自己主要阶段以自己场上1只「破坏之剑士」为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。 ②：这张卡装备中的场合，对方不能把墓地的怪兽的效果发动。 ③：把装备的这张卡送去墓地，以「破坏剑-魔法破坏之剑」以外的自己墓地1只「破坏剑」怪兽为对象才能发动。那只怪兽加入手卡。'),
(42883273, 'Wodan the Resident of the Forest', '森之住人 乌丹', '森の住人 ウダン', 'Effect Monster', 'Warrior', 'EARTH', 3, 900, 1200, '场上每存在1只表侧表示的植物族怪兽，这张卡的攻击力上升100。'),
(62995268, 'Woes of the White Forest', '此乃白森之祸矣', '白き森のわざわいなり', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组把1只「白森林」怪兽特殊召唤。那之后，可以进行1只「白森林」同调怪兽的同调召唤。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(49417509, 'Wolf', '狼', 'オオカミ', 'Normal Monster', 'Beast', 'EARTH', 3, 1200, 800, '比较难见到的狼。用灵敏的鼻子寻找猎物。'),
(56369281, 'Wolf Axwielder', '贝奥武夫狼', 'ベイオウルフ', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1650, 1000, '一旦开始战斗，在没分出胜负之前就不会停止战斗的狂战士。'),
(83546647, 'Wolf in Sheep''s Clothing', '无抵抗的真相', '無抵抗の真相', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的直接攻击让自己受到战斗伤害时，把手卡1只1星怪兽给对方观看发动。给对方观看的1只怪兽和自己卡组存在的1只同名怪兽在自己场上特殊召唤。'),
(45935145, 'Wollow, Founder of the Drudge Dragons', '死祖之隶龙 窝落', '死祖の隷竜ウォロー', 'XYZ Monster', 'Zombie', 'DARK', 6, 2400, 1300, '6星怪兽×2只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽的攻击力·守备力上升对方墓地的卡数量×100。 ②：可以以对方墓地1张卡为对象，把这张卡的超量素材的以下数量取除，那个效果发动。这个效果在对方回合也能发动。 ●1个：那张卡回到卡组。 ●2个：那张卡是怪兽的场合，在自己场上表侧表示或者里侧守备表示特殊召唤。那以外的场合，在自己场上盖放。'),
(78574395, 'Wonder Balloons', '神奇气球', 'ワンダー・バルーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把手卡任意数量送去墓地才能发动。送去墓地的那个数量的气球指示物给这张卡放置。 ②：只要这张卡在魔法与陷阱区域存在，对方场上的怪兽的攻击力下降这张卡的气球指示物数量×300。'),
(38568567, 'Wonder Clover', '奇异三叶草', 'ワンダー・クローバー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽，从手卡把1只4星的植物族怪兽送去墓地发动。选择怪兽在同1次的战斗阶段中可以作2次攻击。这张卡发动的回合，自己场上存在的其他怪兽不能攻击宣言。'),
(50684552, 'Wonder Garage', '神奇车库', 'ワンダーガレージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '盖放的这张卡被破坏送去墓地时，可以从手卡把1只4星以下的名字带有「机人」的机械族怪兽特殊召唤。'),
(67775894, 'Wonder Wand', '神奇魔杖', 'ワンダー・ワンド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '魔法师族怪兽才能装备。 ①：装备怪兽的攻击力上升500。 ②：把装备怪兽和这张卡从自己场上送去墓地才能发动。自己从卡组抽2张。'),
(73860462, 'Wonder Xyz', '奇妙超量', 'ワンダー・エクシーズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：用自己场上的怪兽为素材把1只超量怪兽超量召唤。'),
(17832359, 'Wonko, Noble Knight of the Forest', '森之圣骑士 汪宝', '森の聖騎士 ワンコ', 'Effect Monster', 'Beast', 'LIGHT', 4, 1100, 1600, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「童话故事 序章 启程的曙光」加入手卡。自己的场上或墓地有「童话故事 序章 启程的曙光」存在的场合，作为代替让自己也能抽1张。 ②：只要场地区域有卡存在，对方怪兽不能选择其他怪兽作为攻击对象。 ③：这张卡被战斗破坏时才能发动。让把这张卡破坏的怪兽的攻击力下降500。'),
(47195442, 'Wonky Quartet', '四兽层 摇晃乐师', '四獣層ウォンキー', 'XYZ Monster', 'Beast', 'EARTH', 4, NULL, 2600, '4星怪兽×2只以上 ①：场上的这张卡不受其他卡的效果影响。 ②：这张卡超量召唤的场合或者自己准备阶段发动。从自己卡组上面把3张卡作为这张卡的超量素材。那之后，这张卡作为超量素材中的怪兽数量的以下效果适用。 ●4只以下：这张卡的控制权移给对方。 ●5只以上：自己受到这张卡持有的超量素材数量×400伤害，自己场上的怪兽全部破坏。'),
(17511156, 'Wood Clown', '木灵小丑', 'ウッド・ジョーカー', 'Normal Monster', 'Warrior', 'EARTH', 3, 800, 1200, '作出令人讨厌的笑容的恶魔。以手中的镰刀熟练的回避着攻击。'),
(17733394, 'Wood Remains', '森之尸', '森の屍', 'Normal Monster', 'Zombie', 'DARK', 3, 1000, 900, '森林守护神死后，被恶魔复活的尸体。'),
(35322812, 'Woodborg Inpachi', '人造木人18', '人造木人１８', 'Normal Monster', 'Machine', 'FIRE', 5, 500, 2500, '谜之大木人18号，由魔界尖端技术改造后的姿态。由于重点放在了坚固的装甲上，因此牺牲了机动性。'),
(9848939, 'Woodland Archer', '树海的射手', '樹海の射手', 'Effect Monster', 'Beast-Warrior', 'EARTH', 3, 1400, 1300, '这张卡不能通常召唤。自己墓地通常怪兽有2只以上存在的场合才能特殊召唤。可以把这张卡解放，从自己卡组把1只二重怪兽加入手卡。'),
(6979239, 'Woodland Sprite', '树叶妖精', 'リーフ・フェアリー', 'Effect Monster', 'Plant', 'EARTH', 3, 900, 400, '装备在这张卡上的1张装备卡送去墓地。对方玩家受到500分的伤害。'),
(44928016, 'World Carrotweight Champion', '胡萝卜人', 'にん人', 'Effect Monster', 'Plant', 'DARK', 4, 1900, NULL, '「胡萝卜人」的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合，从手卡以及自己场上的表侧表示怪兽之中把「胡萝卜人」以外的1只植物族怪兽送去墓地才能发动。这张卡从墓地特殊召唤。'),
(84899094, 'World Chalice Guardragon', '星杯守护龙', '星杯の守護竜', 'Effect Monster', 'Dragon', 'WIND', 1, 400, 400, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的连接状态的怪兽为对象的魔法·陷阱·怪兽的效果发动时，把手卡·场上的这张卡送去墓地才能发动。那个发动无效并破坏。 ②：把墓地的这张卡除外，以自己墓地1只通常怪兽为对象才能发动。那只怪兽在作为连接怪兽所连接区的自己场上守备表示特殊召唤。'),
(95793022, 'World Chalice Guardragon Almarduke', '星杯守护龙 魂之马尔杜克', '星杯の守護竜アルマドゥーク', 'Fusion Monster', 'Dragon', 'WIND', 9, 3000, 2600, '连接怪兽×3 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上的上记卡解放的场合可以从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡可以向对方怪兽全部各作1次攻击。 ②：这张卡和对方的连接怪兽进行战斗的攻击宣言时，把连接标记数量和那只对方怪兽相同的1只连接怪兽从自己的场上·墓地除外才能发动。那只对方怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(90173539, 'World Dino Wrestling', '世界恐龙摔跤', 'ワールド・ダイナ・レスリング', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上有「恐龙摔跤手」怪兽存在的场合，双方玩家在战斗阶段只能用1只怪兽攻击。 ②：自己的「恐龙摔跤手」怪兽的攻击力只在向对方怪兽攻击的伤害计算时上升200。 ③：对方场上的怪兽数量比自己场上的怪兽多的场合，把墓地的这张卡除外才能发动。从卡组把1只「恐龙摔跤手」怪兽特殊召唤。'),
(57282724, 'World Gears of Theurlogical Demiurgy', '星神器 造神巨匠', '星神器デミウルギア', 'Link Monster', 'Cyberse', 'DARK', NULL, 3500, NULL, '5星以上的怪兽3只 这张卡不能作为连接素材。这个卡名的②③的效果1回合各能使用1次。 ①：连接召唤的这张卡不受其他怪兽的效果影响。 ②：已用种族和属性不同的怪兽3只为素材让这张卡连接召唤的场合才能发动。场上的其他卡全部破坏。 ③：对方从额外卡组把怪兽特殊召唤的场合才能发动。从卡组把1只「星遗物」怪兽特殊召唤。'),
(42388271, 'World Legacy - "World Ark"', '星遗物－星柜－', '星遺物－『星櫃』', 'Effect Monster', 'Machine', 'DARK', 7, 2500, 500, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上的连接怪兽被对方的效果破坏送去自己墓地的场合，把这张卡从手卡送去墓地，以那1只连接怪兽为对象才能发动。那只怪兽特殊召唤。 ②：怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ③：通常召唤的这张卡在怪兽区域存在，对方从额外卡组把怪兽特殊召唤的场合才能发动。从卡组把1只怪兽送去墓地。'),
(83477829, 'World Legacy - "World Armor"', '星遗物－星铠－', '星遺物－『星鎧』', 'Effect Monster', 'Machine', 'DARK', 7, 2500, 2500, '这个卡名的①②③的效果1回合各能使用1次。 ①：怪兽反转召唤成功时才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「星遗物」卡加入手卡。 ③：通常召唤的这张卡存在的场合，以从额外卡组特殊召唤的对方场上1只表侧表示怪兽为对象才能发动。那只怪兽和这张卡回到持有者手卡。这个效果在对方回合也能发动。'),
(57288708, 'World Legacy - "World Chalice"', '星遗物－星杯－', '星遺物－『星杯』', 'Effect Monster', 'Machine', 'DARK', 5, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：从额外卡组有怪兽特殊召唤的场合，把这张卡解放才能发动。那些怪兽送去墓地。 ②：通常召唤的表侧表示的这张卡从场上离开的场合才能发动。从卡组把「星遗物-『星杯』」以外的2只「星杯」怪兽特殊召唤。 ③：把墓地的这张卡除外才能发动。从卡组把1张「星遗物」卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(27918365, 'World Legacy - "World Crown"', '星遗物－星冠－', '星遺物－『星冠』', 'Effect Monster', 'Machine', 'DARK', 6, 2000, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。 ②：从额外卡组特殊召唤的场上的怪兽的效果发动时，把这张卡解放才能发动。那个发动无效并破坏。 ③：通常召唤的这张卡被解放的场合才能发动。从卡组把1张「星遗物」魔法·陷阱卡加入手卡。'),
(40441990, 'World Legacy - "World Key"', '星遗物－星键－', '星遺物－『星鍵』', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1张「星遗物」卡才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以上级召唤。 ②：这张卡和对方连接怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽回到持有者的额外卡组。'),
(46647144, 'World Legacy - "World Lance"', '星遗物－星枪－', '星遺物－『星槍』', 'Effect Monster', 'Machine', 'DARK', 8, 3000, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：包含连接怪兽的怪兽之间进行战斗的伤害计算时，把这张卡从手卡丢弃才能发动。那只进行战斗的对方怪兽的攻击力下降3000。 ②：只要这张卡在怪兽区域存在，对方不能向其他的「星遗物」怪兽攻击。 ③：从额外卡组有怪兽特殊召唤的场合发动。在双方场上把「星遗物衍生物」（机械族·暗·1星·攻/守0）各1只守备表示特殊召唤。'),
(55787576, 'World Legacy - "World Shield"', '星遗物－星盾－', '星遺物－『星盾』', 'Effect Monster', 'Machine', 'DARK', 6, NULL, 3000, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，不受从额外卡组特殊召唤的怪兽发动的效果影响。 ②：和这张卡相同纵列的自己的「星遗物」卡不会成为对方的效果的对象，不会被对方的效果破坏。 ③：这张卡在墓地存在的场合，自己·对方的准备阶段支付1000基本分才能发动。这张卡从墓地特殊召唤。那之后，对方可以从自身的手卡·墓地选1只怪兽特殊召唤。'),
(93920420, 'World Legacy - "World Wand"', '星遗物－星杖－', '星遺物－『星杖』', 'Effect Monster', 'Machine', 'DARK', 8, 500, 2500, '这个卡名的②③的效果1回合各能使用1次。 ①：通常召唤的这张卡不会被和从额外卡组特殊召唤的怪兽的战斗破坏。 ②：这张卡被送去墓地的场合才能发动。从手卡把1只「星遗物」怪兽特殊召唤。 ③：把墓地的这张卡除外，以自己的除外状态的1只「自奏圣乐」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。'),
(12989604, 'World Legacy Awakens', '从星遗物的苏醒', '星遺物からの目醒め', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：用自己场上的怪兽为素材把1只连接怪兽连接召唤。'),
(59778096, 'World Legacy Bestowal', '星遗物之选讬', '星遺物の選託', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●选对方场上1只连接怪兽送去墓地。 ●从自己墓地把7张「星遗物」卡除外才能发动。从卡组把1只电子界族怪兽加入手卡。');